{
  "states": [
    "INIT",
    "BOUND",
    "RENEWING",
    "REBINDING"
  ],
  "transitions": [
    {
      "from": "INIT",
      "event": "Receive DHCPACK",
      "action": "moving to BOUND state",
      "to": "BOUND"
    },
    {
      "from": "INIT",
      "event": "Receive neither DHCPACK nor DHCPNAK",
      "action": "MAY choose to use previously allocated network address and configuration parameters",
      "to": "BOUND"
    },
    {
      "from": "BOUND",
      "event": "Receive DHCPNAK",
      "action": "reverts to INIT state",
      "to": "INIT"
    },
    {
      "from": "BOUND",
      "event": "Send DHCPDECLINE",
      "action": "restarts the configuration process",
      "to": "INIT"
    },
    {
      "from": "RENEWING",
      "event": "Receive DHCPNAK",
      "action": "moving to the INIT state",
      "to": "INIT"
    },
    {
      "from": "REBINDING",
      "event": "Receive DHCPNAK",
      "action": "moving to the INIT state",
      "to": "INIT"
    }
  ]
}

{
  "states": [
    "INIT",
    "INIT-REBOOT",
