      "action": "Select offer, send DHCPREQUEST",
      "to": "SELECTING"
    },
    {
      "from": "SELECTING",
      "event": "Send DHCPREQUEST",
      "action": "Broadcast DHCPREQUEST",
      "to": "REQUESTING"
    },
    {
      "from": "REQUESTING",
      "event": "DHCPACK",
      "action": "Record lease, set timers T1, T2",
      "to": "BOUND"
    },
    {
      "from": "REQUESTING",
      "event": "DHCPNAK",
      "action": "Halt network",
      "to": "REBOOTING"
    },
    {
      "from": "INIT-REBOOT",
      "event": "DHCPACK",
      "action": "Record lease, set timers T1, T2",
      "to": "BOUND"
    },
    {
      "from": "INIT-REBOOT",
      "event": "DHCPNAK/Restart",
      "action": "Restart",
      "to": "INIT"
    },
    {
      "from": "REBOOTING",
      "event": "DHCPACK",
      "action": "Record lease, set timers T1, T2",
      "to": "BOUND"
    },
    {
      "from": "REBOOTING",
      "event": "DHCPNAK/Restart",
      "action": "Restart",
      "to": "INIT-REBOOT"
    },
    {
      "from": "BOUND",
      "event": "T1 expires",
      "action": "Send DHCPREQUEST",
      "to": "RENEWING"
    },
    {
      "from": "RENEWING",
      "event": "DHCPACK",
      "action": "Record lease, set timers T1, T2",
      "to": "BOUND"
    },
